contents['email-settings']=()=>settingsTabs('email-settings')+panel('Senders & reply routing',detail('B2B sender','Parth · parth@trypromunch.in')+detail('B2B reply-to','parth@trypromunch.in')+detail('Deals mailbox','hello@promunch.in')+badge('Reply bridge not verified','amber')+note('Before automatic deal creation, ensure replies to Parth reach the monitored pipeline with the correct company and thread association.')+detail('Marketing','Use the sender verified for the chosen provider')+detail('Existing recovery messages','Preserve the active Resend recovery engine'));
contents.brand=()=>settingsTabs('brand')+panel('Brand settings',field('Brand name','PROMUNCH')+field('Tagline','Your Munchy Pal')+note('The current persistence path needs verification. Show a clear unavailable state until saves are confirmed by the server.')+`<button disabled>Save unavailable</button>`);
contents.activity=()=>toolbar('Search activity',['All events','Failures','Settings','Customer actions'])+panel('Activity log',table(['When','What changed','Who / source','Result'],[['12:04','Inventory sync','Amazon connector',badge('Succeeded','green')],['11:55','Ticket assigned','Team member',badge('Saved','green')],['11:42','Contact sync','Brevo connector',badge('Needs review','amber')]]));
contents.assistant=()=>window.mayaScreen();
contents.unavailable=()=>panel('Not available in the current app',table(['Feature','Navigation treatment','Reason'],[['SMS','Hidden','Not used'],['Creative partnerships / Instagram','Hidden from daily navigation','Backend not live'],['Voice features','Hidden until verified','No verified operational flow'],['Unconnected Brevo automations','Hidden or explicitly unavailable','API connection does not establish feature support'],['Legacy duplicate campaigns / analytics','Consolidate / redirect','Use the canonical channel screens']]))+note('Retain working background processes. Removing a navigation item does not delete business data or disable a live recovery engine.');
contents.more=()=>navigationDirectory();
contents.login=()=>`<div class="auth"><a class="logo" href="#login">${brandLogo()}</a><h1>Sign in</h1><p class="muted">Your business, in one place.</p><form data-auth="home">${field('Work email','','email')}${field('Password','','password')}<button class="primary">Sign in to prototype</button></form><p>${link('password','Set or reset password')}</p><small>Demo only. Do not enter a real password.</small></div>`;
contents.password=()=>`<div class="auth">${brandLogo()}<h1>Set your password</h1><form data-auth="home">${field('New password','','password')}${field('Confirm password','','password')}<button class="primary">Save demo password</button></form><small>Use sample text only. Nothing is sent or stored.</small></div>`;
contents.unsubscribe=()=>`<div class="auth">${brandLogo()}<h1>Email preferences</h1><p>Choose whether to receive marketing emails.</p>${button('Unsubscribe from marketing','unsubscribe',true)}<p><small>Order-related updates are managed separately.</small></p></div>`;
function reviewCount(){return companyNames.filter((_,i)=>sessionStorage.getItem('review-'+i)).length}
function current(){return location.hash.slice(1).split('?')[0]||'home'}
const descriptions={home:'Today’s business, plus the issues that need you.',stock:'Keep the right products sellable. Act on profit at risk first.',profit:'See what each product contributes, with cost gaps clearly marked.',payouts:'Check Amazon deductions, expected amounts and bank receipts separately.',inbox:'Urgent and unresolved customers come first.',deals:'Active buyer conversations, with a clear next action.',leads:'One reviewed process from finding companies to handling replies.'};
function nav(){return navigationSidebar()}
function render(){window.closePMSelect?.();let id=current(),s=SCREENS.find(x=>x.id===id)||SCREENS[0];if(!contents[id])id='home';const params=new URLSearchParams(location.hash.split('?')[1]||'');const chosen=params.get('design');if(['soft','bold','compact'].includes(chosen))sessionStorage.setItem('pm-design',chosen);activeDesign=chosen||activeDesign||'bold';document.body.dataset.design=activeDesign;const state=params.get('state')||'normal';let body=contents[id]();if(state==='loading')body=`<div aria-busy="true" role="status"><p>Loading ${s.title.toLowerCase()}…</p><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div>`;if(state==='empty')body=panel('Nothing to show yet',`<div class="empty"><h2>No ${s.group==='Amazon'?'synced records':'items'} in this view</h2><p>Check the selected period and filters, or connect the source to get started.</p>${link(id,'Reset filters')} ${link('settings','Check connection')}</div>`);if(state==='error')body=panel('This view could not load',`<div class="empty"><h2>Your data is safe</h2><p>The source did not respond. Try again or check the connection.</p>${link(id,'Try again',true)} ${link('settings','Connection details')}</div>`);if(state==='denied')body=panel('Access required',`<div class="empty"><h2>You do not have access to this view</h2><p>Ask your workspace owner to review your role.</p>${link('home','Back to home')}</div>`);if(state==='stale')body=`<div class="alert amber"><div><strong>Data is out of date</strong><p>Last successful refresh: yesterday, 18:40 IST. Review the connection before acting on stock or money figures.</p></div>${link('settings','Check sync')}</div><br>`+body;
const account=s.group==='Account';$('#root').innerHTML=account?`<div class="notice">Design prototype · Sample inputs only</div>${body}`:`<div class="shell"><aside class="sidebar" aria-label="Main navigation">${nav()}</aside><div><header class="top"><span class="mobile-only">${brandLogo(true)}</span><button class="search" data-action="search">Find a page or action</button><div class="row"><a class="btn maya-global" href="#assistant">✧ Ask Maya</a><span class="meta">21 Sep 2026 · IST</span><a href="#settings" class="avatar" aria-label="Workspace settings">PM</a></div></header><div class="notice">Illustrative data · Prototype actions only</div><main class="main" id="main" data-group="${s.group}" data-screen="${id}">${navigationContext()}<div class="pagehead"><div><div class="page-category">${visualIcon(({Overview:"home",Sales:"chart",Amazon:"box",Support:"inbox",B2B:"people",Marketing:"flag",WhatsApp:"inbox",Customers:"people",Settings:"gear"})[s.group])}<span>${s.group}</span></div><h1>${s.title.replace(/^\d\. /,'')}</h1><span class="muted page-description">${descriptions[id]||''}</span></div></div><div class="stack">${body}</div></main></div></div><nav class="bottom" aria-label="Mobile navigation">${[['home','Home','home'],['inbox','Inbox','inbox'],['stock','Amazon','amazon'],['more','More','grid']].map(([key,label,ic])=>`<a href="#${key}" class="${key===id?'on':''}">${icon(ic)}${label}</a>`).join('')}</nav>`;document.title=`${s.title} · PROMUNCH`;parent.postMessage({screen:id,route:location.hash.slice(1)},'*');bind();window.scrollTo(0,0)}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5500)}
function modal(title,body){$('#dialog').innerHTML=`<h2>${title}</h2><div style="margin-top:16px">${body}</div><div class="row"><button data-close>Close</button></div>`;$('#dialog').showModal();$('#dialog').querySelector('[data-close]').onclick=()=>$('#dialog').close()}
function bind(){
 const skip=document.querySelector('.skip');if(skip)skip.onclick=e=>{e.preventDefault();const m=$('#main');if(m){m.tabIndex=-1;m.focus()}};
 const quantity=$('#quantity');if(quantity){quantity.value=sessionStorage.getItem('planned-quantity')||'480';quantity.oninput=()=>sessionStorage.setItem('planned-quantity',quantity.value)}
 if(current()==='shipment'){const n=Number(sessionStorage.getItem('planned-quantity')||480);const cells=document.querySelectorAll('tbody td');if(cells.length>=4){cells[1].textContent=n+' units';cells[2].textContent=(n/12)+' × 12';cells[3].textContent=(640-n)+' units'} }
 document.querySelectorAll('#draft-list details').forEach((d,i)=>{d.querySelectorAll('input[type=text],textarea').forEach((f,j)=>{const key='draft-edit-'+i+'-'+j;const saved=sessionStorage.getItem(key);if(saved!==null)f.value=saved;f.oninput=()=>{sessionStorage.setItem(key,f.value);sessionStorage.removeItem('review-'+i);d.querySelector('[data-review]').checked=false;updateReview()}})});
 const rank=$('[data-rank]');if(rank)rank.onchange=()=>{const body=document.querySelector('tbody');const rows=[...body.rows];if(rank.value==='Units sold')rows.sort((a,b)=>Number(b.cells[2].textContent.replace(/,/g,''))-Number(a.cells[2].textContent.replace(/,/g,'')));else rows.sort((a,b)=>Number(b.cells[1].textContent.replace(/[^0-9]/g,''))-Number(a.cells[1].textContent.replace(/[^0-9]/g,'')));rows.forEach(r=>body.append(r));$('.panelhead h2').textContent='Products · ranked by '+rank.value.toLowerCase()};
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action,b));document.querySelectorAll('form[data-form]').forEach(f=>f.onsubmit=e=>{e.preventDefault();if(current()==='conversation'){const ta=f.querySelector('textarea');const bubble=document.createElement('div');bubble.className='bubble out';bubble.textContent=ta.value;$('.messages').append(bubble);ta.value='';}modal('Prototype result',`<p>${esc(f.dataset.form)}</p>`)});document.querySelectorAll('form[data-auth]').forEach(f=>f.onsubmit=e=>{e.preventDefault();if(current()==='password'){const p=f.querySelectorAll('input');if(!p[0].value||p[0].value!==p[1].value){toast('Enter matching sample passwords.');return}}location.hash=f.dataset.auth});document.querySelectorAll('[data-review]').forEach(c=>c.onchange=()=>{if(c.checked)sessionStorage.setItem('review-'+c.dataset.review,'yes');else sessionStorage.removeItem('review-'+c.dataset.review);updateReview()});updateReview();document.querySelectorAll('[data-filter]').forEach(inp=>inp.oninput=()=>filterRows());document.querySelectorAll('[data-status-filter]').forEach(sel=>sel.onchange=()=>filterRows());document.querySelectorAll('[data-chat-filter]').forEach(inp=>inp.oninput=()=>document.querySelectorAll('.chatlist>a').forEach(a=>a.hidden=!a.textContent.toLowerCase().includes(inp.value.toLowerCase())));const period=$('[data-top-period]');if(period)period.onchange=()=>{const k=document.querySelectorAll('.kpi')[2];k.querySelector('.name>span').textContent='Top product · '+period.value;k.querySelector('strong').textContent=period.selectedIndex===2?'Classic':'Peri Peri';k.querySelector('small').textContent=['₹1,42,800 revenue · 340 units','₹4,26,000 revenue · 1,080 units','₹12,10,000 revenue · 3,210 units'][period.selectedIndex]};window.enhancePMSelects();window.enhancePremium();window.bindMaya();window.bindOutreach();window.bindListings();window.bindVisual();window.bindPipeline();window.bindNavigation();window.bindWhatsAppUI();window.bindCustomerWorkspace();window.bindEmailReview();}
function filterRows(){const q=$('[data-filter]')?.value.toLowerCase()||'',s=$('[data-status-filter]')?.value||'';let visible=0;document.querySelectorAll('tbody tr').forEach(r=>{const t=r.textContent.toLowerCase();const status=/^(all|open tickets)/i.test(s)||t.includes(s.toLowerCase());r.hidden=!(t.includes(q)&&status);if(!r.hidden)visible++});let empty=$('#filter-empty');if(!empty){empty=document.createElement('p');empty.id='filter-empty';empty.className='callout';$('.main .stack').append(empty)}empty.textContent=visible?'':'No matching rows. Try another search or reset the filter.';empty.hidden=!!visible}
function updateReview(){document.querySelectorAll('#draft-list details').forEach((d,i)=>{const b=d.querySelector('summary .badge');if(b){const ok=!!sessionStorage.getItem('review-'+i);b.textContent=ok?'Reviewed':'Needs review';b.className='badge '+(ok?'green':'amber')}});if($('#review-count'))$('#review-count').textContent=`${reviewCount()} of 10 drafts reviewed`;}
function act(action,b){const confirmed=()=>{if(!$('[data-confirm]')?.checked){toast('Complete the review checkbox first.');return false}return true};if(action==='shipment'){const n=Number(sessionStorage.getItem('planned-quantity')||480);if(n<=0||n>480||n%12!==0){toast('Choose full cartons of 12, up to 480 transferable units.');return}}if(action==='batch'){if(reviewCount()!==10){modal('Review all 10 emails first',`<p>${reviewCount()} of 10 reviewed. Each recipient and personalized draft needs review.</p>${link('review','Return to drafts',true)}`);return}if(!confirmed())return;modal('Sample batch approved','<p>10 reviewed drafts approved in this prototype. No real emails sent.</p>'+link('replies','View sample reply tracking'));return}if(['shipment','schedule','waapprove'].includes(action)){if(!confirmed())return;modal('Sample review complete','<p>Your sample confirmation was recorded for this preview. No shipment, message or schedule was created in production.</p>');return}if(action==='search'){modal('Find a page',`<label class="field">Page name<input id="page-search" placeholder="Stock, Deals, Inbox…"></label><div id="page-results" class="stack">${SCREENS.filter(x=>x.group!=='Account'&&x.id!=='unavailable').map(s=>`<a href="#${s.id}">${s.title}</a>`).join('')}</div>`);$('#page-search').oninput=e=>$('#page-results').querySelectorAll('a').forEach(a=>a.hidden=!a.textContent.toLowerCase().includes(e.target.value.toLowerCase()));return}if(action==='assign'){b.textContent='Assigned to me';toast('Sample ticket assigned to you.');return}if(action==='import'){modal('2. Check columns',table(['File column','Customer field'],[['name','Full name'],['phone','Phone'],['email','Email (optional)'],['consent_source','Consent evidence']])+`<p>Sample file: 10 rows · 8 ready · 1 duplicate · 1 missing identity.</p><button id="import-next" class="primary">Review 8 eligible rows</button>`);$('#import-next').onclick=()=>{modal('3. Review & import','<p>8 eligible sample records. Duplicate skipped; invalid row excluded. Imported contacts remain unsubscribed unless valid consent evidence exists.</p><button id="import-final" class="primary">Simulate import</button>');$('#import-final').onclick=()=>modal('Sample import complete','<p>8 sample rows accepted. No customer records were changed.</p>')};return}const details={save:['Saved locally for review','This is a sample confirmation. No production settings were changed.'],bank:['Bank check preview','Production must compare amount, currency, settlement reference and receipt date. No bank match was recorded.'],note:['Settlement review note','Document the expected fee, Amazon fee, source rule and evidence.'],dispatch:['Dispatch evidence','Record carrier, tracking reference and dispatch date before moving to Samples sent. Acceptance alone is not dispatch.'],emailreply:['Review outgoing reply','Confirm the recipient, exact reply text and order facts. This prototype does not send email.'],followup:['Review follow-up','Check the latest reply first. A promised date or recent inbound response overrides the suggested follow-up.'],testemail:['Test preview','No test email sent. In production, verify the test recipient before sending.'],previewlink:['Button destination','The sample button points to promunch.in.'],coupon:['Coupon details','WELCOME5 · 5% prepaid discount · Eligibility and usage limits supplied by Shopify.'],template:['Template submission preview','Review category, language, variable examples and STOP footer. No Meta submission made.'],connection:['Connection details','Show last successful sync, records imported, recent error and next retry. Secrets remain hidden.'],access:['Role access','Support: conversations and tickets. Analyst: permitted reporting. Owner: financial and integration controls according to verified role rules.'],rotate:['Rotate credential','Owner-only. Enter a replacement, validate it, then atomically replace the current secret. This prototype does not collect credentials.'],unsubscribe:['Preference preview','You are unsubscribed in this sample view. No real subscription was changed.']};const d=details[action]||details.save;modal(d[0],`<p>${d[1]}</p>`)}
window.addEventListener('hashchange',()=>{if($('#dialog').open)$('#dialog').close();render()});render();
